    // Iterate through each character in the string
    for i := 0 to length - 1 {
        var ch := s[i];
        // Check for lowercase vowels
        if ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u' {
            count := count + 1;
        }
        // Check for uppercase vowels
        if ch == 'A' || ch == 'E' || ch == 'I' || ch == 'O' || ch == 'U' {
            count := count + 1;
        }
    }
    // Check for 'y' at the end
    if length > 0 && s[length - 1] == 'y' || s[length - 1] == 'Y' {
        count := count + 1;
    }
    return count;
}
